package com.vms.api.video.domain;

import java.util.UUID;

/**
 * Storage object keys are always generated by the server from ids, never from user input, so they
 * cannot collide or be used for path traversal.
 */
public final class ObjectKeys {

  private ObjectKeys() {}

  public static String raw(UUID ownerId, UUID videoId, String baseContentType) {
    String extension = "video/mp4".equals(baseContentType) ? "mp4" : "webm";
    return "raw/" + ownerId + "/" + videoId + "." + extension;
  }

  public static String watermarked(UUID ownerId, UUID videoId) {
    return "videos/" + ownerId + "/" + videoId + ".mp4";
  }
}
